import{_ as n,a0 as s,w as l,s as d,ao as p,I as i,x as r,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux上从MySQL迁移到MariaDB的简单步骤 | LCTT x X-CMD","titleTemplate":false,"description":"Linux上从MySQL迁移到MariaDB的简单步骤 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux上从MySQL迁移到MariaDB的简单步骤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux上从MySQL迁移到MariaDB的简单步骤 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150211 Simple Steps Migration From MySQL To MariaDB On Linux","title":"Linux上从MySQL迁移到MariaDB的简单步骤","tag":"201504","desc":""},"relativePath":"201504/20150211 Simple Steps Migration From MySQL To MariaDB On Linux.md","filePath":"[post].md"}'),m={name:"201504/20150211 Simple Steps Migration From MySQL To MariaDB On Linux.md"};function g(y,a,u,c,b,M){const t=s("Link");return l(),d("div",null,[a[16]||(a[16]=p(`<h1 id="linux上从mysql迁移到mariadb的简单步骤" tabindex="-1">Linux上从MySQL迁移到MariaDB的简单步骤 <a class="header-anchor" href="#linux上从mysql迁移到mariadb的简单步骤" aria-label="Permalink to “Linux上从MySQL迁移到MariaDB的简单步骤”">​</a></h1><p>大家好！这是一篇介绍如何在服务器或个人电脑上从MySQL迁移到MariaDB的教程。也许你会问为什么我们要将数据库管理从MySQL迁移到MariaDB。往下看我们告诉你为什么这样做。</p><h3 id="为什么要用mariadb来代替mysql" tabindex="-1">为什么要用MariaDB来代替MySQL <a class="header-anchor" href="#为什么要用mariadb来代替mysql" aria-label="Permalink to “为什么要用MariaDB来代替MySQL”">​</a></h3><p>MariaDB是MySQL社区开发的分支，也是一个增强型的替代品。它由MySQL前开发者们带头组织的基金会开发，使用起来和MySQL完全一样。自从Oracle买下了MySQL，它就不再自由开源了，但是 <strong>MariaDB仍然自由开源</strong>。一些如谷歌、维基、LinkedIn、Mozilla等的顶级的网站已经迁移到MariaDB了。它的优势在哪里：</p><ul><li>向后兼容MySQL</li><li>永远开源</li><li>由MySQL缔造者的维护</li><li>更尖端的功能</li><li>更多的存储引擎</li><li>大型的网站已经转向MariaDB</li></ul><p>现在，让我们迁移到MariaDB吧！</p><p>让我们创建一个叫<strong>linoxidedb</strong>的<strong>用于测试的</strong>示例数据库。</p><p>使用以下命令用root账户登陆MySQL：</p><pre><code>$ mysql -u root -p
</code></pre><p>输入mysql 的 root 用户密码后，你将进入<strong>mysql的命令行</strong></p><p><strong>创建测试数据库:</strong></p><p>在mysql命令行输入以下命令以创建测试数据库。</p><pre><code>mysql&gt; create database linoxidedb;
</code></pre><p>查看可用的数据库，输入以下命令：</p><pre><code>mysql&gt; show databases;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/creating-test-databases.png" alt="creating test databases"></p><p>如你所见，算上刚刚新建的linoxidedb我们一共有5个数据库。</p><pre><code>mysql&gt; quit
</code></pre><p>现在，我们就将刚创建的数据库从MySQL迁移到MariaDB。</p><p>注：使用CentOS这类基于fedora的linux发行版没有必要参考这篇教程，因为它们在安装MariaDB时会自动代替MySQL，无需备份现有的数据库，你只需要更新mysql就可以得到mariadb。</p><h3 id="_1-备份现有的数据库" tabindex="-1">1. 备份现有的数据库 <a class="header-anchor" href="#_1-备份现有的数据库" aria-label="Permalink to “1. 备份现有的数据库”">​</a></h3><p>我们第一个重要的步骤就是备份现有的数据库。我们在<strong>终端（不是MySQL命令行）</strong>里输入如下命令来完成备份。</p><pre><code>$ mysqldump --all-databases --user=root --password --master-data &gt; backupdatabase.sql
</code></pre><p>哇哦！我们遇到了点麻烦。别担心我们可以搞定。</p><pre><code>$ mysqldump: Error: Binlogging on server not active
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mysqldump-error.png" alt=""></p><p><em>mysqldump error</em></p><p>为了修复这个错误，我们需要对<strong>my.cnf</strong>文件做一些小改动。</p><p>编辑my.cnf文件：</p><pre><code>$ sudo nano /etc/mysql/my.cnf
</code></pre><p>在[mysqld]部分添加如下参数。</p><p><strong>log-bin=mysql-bin</strong></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/configuring-my.cnf_.png" alt="configuring my.cnf"></p><p>好了，在保存并关闭文件后，我们需要重启一下mysql服务。运行以下命令重启：</p><pre><code>$ sudo /etc/init.d/mysql restart
</code></pre><p>现在，重新运行mysqldump命令来备份所有的数据库。</p><pre><code>$ mysqldump --all-databases --user=root --password --master-data &gt; backupdatabase.sql
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/crearing-bakup-file.png" alt=""></p><p><em>dumping databases</em></p><p>上面的命令将会备份所有的数据库，把它们存储在当前目录下的<strong>backupdatabase.sql</strong>文件中。</p><h3 id="_2-卸载mysql" tabindex="-1">2. 卸载MySQL <a class="header-anchor" href="#_2-卸载mysql" aria-label="Permalink to “2. 卸载MySQL”">​</a></h3><p>首先，我们得把<strong>my.cnf文件挪到安全的地方去</strong>。</p><p><strong>注</strong>：在你卸载MySQL包的时候不会自动删除my.cnf文件，我们这样做只是以防万一。在MariaDB安装时，它会询问我们是保持现存的my.cnf文件，还是使用包中自带的版本（即新my.cnf文件）。</p><p>在shell或终端中输入如下命令来备份my.cnf文件：</p><pre><code>$ sudo cp /etc/mysql/my.cnf my.cnf.bak
</code></pre><p>运行命令来终止mysql服务：</p><pre><code>$ sudo /etc/init.d/mysql stop
</code></pre><p>然后移除mysql包：</p><pre><code>$ sudo apt-get remove mysql-server mysql-client
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/uninstalling-mysql.png" alt="uninstalling mysql"></p><h3 id="_3-安装mariadb" tabindex="-1">3. 安装MariaDB <a class="header-anchor" href="#_3-安装mariadb" aria-label="Permalink to “3. 安装MariaDB”">​</a></h3><p>这是在Ubuntu系统中安装MariaDB的命令：</p><pre><code>$ sudo apt-get install software-properties-common
$ sudo apt-key adv --recv-keys --keyserver hkp://keyserver.ubuntu.com:80 0xcbcb082a1bb943db
# sudo add-apt-repository &#39;deb http://mirror.mephi.ru/mariadb/repo/5.5/ubuntu trusty main&#39;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/adding-repo-mariadb.png" alt="adding mariadb repo"></p><p>键值导入并且添加完仓库后，你就可以用以下命令安装MariaDB了：</p><pre><code>$ sudo apt-get update
$ sudo apt-get install mariadb-server
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/installing-mariadb.png" alt="installing mariadb"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/my.conf-configuration-prompt.png" alt="my.conf configuration prompt"></p>`,58)),i("p",null,[a[1]||(a[1]=r("我们应该还没忘记在MariaDB安装时，它会问你是使用现有的my.cnf文件，还是包中自带的版本。你可以使用以前的my.cnf也可以用包中自带的。即使你想直接使用新的my.cnf文件，你依然可以晚点时候将以前的备份内容还原进去（别忘了我们已经将它复制到安全的地方了）。所以，我们直接选择了默认的选项“N”。如果需要安装其他版本，请参考",-1)),e(t,{href:"https://downloads.mariadb.org/mariadb/repositories/#mirror=mephi"},{default:o(()=>[...a[0]||(a[0]=[r("MariaDB官方仓库",-1)])]),_:1}),a[2]||(a[2]=r("。",-1))]),a[17]||(a[17]=p(`<h3 id="_4-恢复配置文件" tabindex="-1">4. 恢复配置文件 <a class="header-anchor" href="#_4-恢复配置文件" aria-label="Permalink to “4. 恢复配置文件”">​</a></h3><p>想要将my.cnf.bak中的内容恢复到my.cnf，在终端中输入以下命令。由于my.cnf.bak文件在当前目录下，所以我们只要简单的执行以下命令即可：</p><pre><code>$ sudo cp my.cnf.bak /etc/mysql/my.cnf
</code></pre><h3 id="_5-导入数据库" tabindex="-1">5. 导入数据库 <a class="header-anchor" href="#_5-导入数据库" aria-label="Permalink to “5. 导入数据库”">​</a></h3><p>最后，让我们把我们之前创建的数据库导入吧！运行一下命令即可完成导入。</p><pre><code>$ mysql -u root -p &lt; backupdatabase.sql
</code></pre><p>就这样，我们已成功将之前的数据库导入了进来。</p><p>来，让我们登录一下mysql命令行，检查一下数据库是否真的已经导入了：</p><pre><code>$ mysql -u root -p
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/importing-database.png" alt="importing database"></p><p>为了检查数据库是否被迁移到MariaDB，请在MariaDB命令行中输入“<strong>show databases</strong>；”不用输入（“”），如下：</p><pre><code>mariaDB&gt; show databases;
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/maria-database-migrated.png" alt="mysql to mariadb database migrated"></p><p>如你所见，linoxidedb及所有的数据库都已经成功的被迁移了。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>最后，我们已经成功地从MySQL迁移到了MariaDB数据库管理系统。MariaDB比MySQL好，虽然在性能方面MySQL还是比它更快，但是MariaDB的优点在于它额外的特性与支持的许可证。这能够确保它自由开源（FOSS），并永久自由开源，相比之下MySQL还有许多额外的插件，有些不能自由使用代码、有些没有公开的开发进程、有些在不久的将来会变的不再自由开源。如果你有任何的问题、评论、反馈给我们，不要犹豫直接在评论区留下你的看法。谢谢观看本教程，希望你能喜欢MariaDB。</p><hr>`,17)),i("p",null,[a[4]||(a[4]=r("via: ",-1)),e(t,{href:"http://linoxide.com/linux-how-to/migrate-mysql-mariadb-linux/"},{default:o(()=>[...a[3]||(a[3]=[r("http://linoxide.com/linux-how-to/migrate-mysql-mariadb-linux/",-1)])]),_:1})]),i("p",null,[a[8]||(a[8]=r("作者：",-1)),e(t,{href:"http://linoxide.com/author/arunp/"},{default:o(()=>[...a[5]||(a[5]=[r("Arun Pyasi",-1)])]),_:1}),a[9]||(a[9]=r(" 译者：",-1)),e(t,{href:"https://github.com/martin2011qi"},{default:o(()=>[...a[6]||(a[6]=[r("martin2011qi",-1)])]),_:1}),a[10]||(a[10]=r(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:o(()=>[...a[7]||(a[7]=[r("wxy",-1)])]),_:1})]),i("p",null,[a[13]||(a[13]=r("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[11]||(a[11]=[r("LCTT",-1)])]),_:1}),a[14]||(a[14]=r(" 原创翻译，",-1)),e(t,{href:"http://linux.cn/"},{default:o(()=>[...a[12]||(a[12]=[r("Linux中国",-1)])]),_:1}),a[15]||(a[15]=r(" 荣誉推出",-1))])])}const S=n(m,[["render",g]]);export{L as __pageData,S as default};
